"""Bind observed recurring failures to immutable native results, without repairs."""
import datetime,hashlib,json,uuid
from pathlib import Path
r=Path('runs/instruction-effects/eval-016');sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();out=Path('.local/eval016-task021-recurring-failures001.json');pending=Path('.local/eval016-task021-pending-lessons001.jsonl');assert not out.exists() and not pending.exists()
rows=[]
for b in ('b004','b008','b011'):
 p=r/f'tasks/task-021/attempts/{b}/attempt-001/result.json';d=json.loads(p.read_text());assert not d['accepted'];index=r/f'builders/{b}/checkpoints/task-021-attempt-001/index.json';i=json.loads(index.read_text());assert i['source_commit']==d['commit'];failures=[{k:x[k] for k in ('test','phase','status','errors')} for x in d['diagnostics'] if x['test'].startswith(('011','073'))];assert any(x['test'].startswith('073') for x in failures)
 rows.append({'builder':b,'attempt':'attempt-001','result':str(p),'result_sha256':sha(p),'source_index':str(index),'source_index_sha256':sha(index),'commit':d['commit'],'tree':d['tree'],'failures':failures})
date=[x for x in rows[0]['failures'] if x['test'].startswith('011')];assert len(date)==1 and 'Received: ""' in date[0]['errors'][0]
repairs=[]
for b in ('b008','b011'):
 p=r/f'tasks/task-021/attempts/{b}/attempt-002/result.json';d=json.loads(p.read_text());assert d['accepted'];events=[json.loads(x) for x in (r/'events.jsonl').read_text().splitlines()];assert any(x['kind']=='post_deployment_checks_passed' and x.get('task_id')=='task-021' and x.get('builder_id')==b and x.get('attempt_id')=='attempt-002' for x in events);repairs.append({'builder':b,'result':str(p),'sha256':sha(p),'commit':d['commit'],'deployment_checked':True})
proof={'verified':True,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'controller_sha256':sha(Path(__file__)),'rejected_originals':rows,'measured_accepted_repairs':repairs,'native_model_calls':0,'scope':'Original result and source-index hashes bound; common021 is still pending. Native archives are retained; this producer does not independently restore their Git histories or diagnose implementation causes. No source, acceptance, feedback, treatment or measurement change.'}
out.write_text(json.dumps(proof,indent=2)+'\n')
common={'schema_version':1,'utc':proof['utc'],'author':'pm','status':'observed','verification':{'proof':str(out),'sha256':sha(out),'controller':str(Path(__file__)),'controller_sha256':sha(Path(__file__))},'comparison_policy':'Observation only; rejected attempts and all measured repairs retained. No treatment-effect inference or PM source, feedback, test or protocol change. Outside the scanned closed020 publication target.','evidence':[str(out),str(Path(__file__))]}
records=[{**common,'record_id':str(uuid.uuid4()),'lesson_id':'L072','scope':'eval016 task021 repeated Unicode title-ordering failures','observation':'Three original submissions (b004,b008,b011) fail073 with U+E000 and U+1F642 in reversed order against the stated Unicode code-point ordering contract. Measured b008/b011 attempt002 repairs pass unchanged acceptance, prior upgrade, actual restart and deployment checks; common021 remains pending.','root_cause':'Incorrect observed ordering confirmed in original results. Underlying comparator implementation cause and causal repair mechanism are unexamined.','prevention':'Keep the existing frozen supplementary-plane code-point fixture and factual expected/received diagnostics. Preserve failed and repaired histories; attribute instruction effects only through the preregistered independent comparison.'},{**common,'record_id':str(uuid.uuid4()),'lesson_id':'L069','scope':'eval016 task021 b004 date-seed recurrence','observation':'Original b004 task021 submission again fails011: expected2028-02-29, received empty date. This record binds the original diagnostic and source index; current repair is pending.','root_cause':'Recurring empty-date assertion confirmed. The prior task015/task017 detached-save trace mechanism is not independently diagnosed for this new attempt.','prevention':'Retain original trace/result/source before measured repair and keep uniform factual feedback. Do not treat earlier accepted repairs as proof that the timing-sensitive sequence was causally fixed.'}]
pending.write_text(''.join(json.dumps(x,sort_keys=True)+'\n' for x in records));print(json.dumps({'verified':True,'unicode_rejections':3,'accepted_repairs':2,'pending_lessons':2,'evidence':str(out)}))
